        .z(z)
    );

    // Clock generation: 10ns period
    initial begin
        clk = 1'b0;
        forever #5 clk = ~clk;
    end

    // Task to check outputs using 4-state case inequality (!==)
    task check_output;
        input expected_z;
        begin
            @(posedge clk);
            #1; // Small delay to allow combinational outputs to settle after clock edge
            if (z !== expected_z) begin
                $display("Mismatch at time %0t: x=%b, z=%b, expected_z=%b", $time, x, z, expected_z);
                errors = errors + 1;
