        // Release reset
        @(negedge clk);
        areset = 1'b0;

        // State A: x=0 -> stays A, z=0
        x = 1'b0;
        check_output(1'b0);

        // State A: x=1 -> goes to B, z=1
        x = 1'b1;
        check_output(1'b1);

        // State B: x=0 -> stays B, z=1
        x = 1'b0;
        check_output(1'b1);

        // State B: x=1 -> stays B, z=0
        x = 1'b1;
        check_output(1'b0);

        // State B: x=1 -> stays B, z=0
        x = 1'b1;
        check_output(1'b0);

        // State B: x=0 -> stays B, z=1
        x = 1'b0;
        check_output(1'b1);

        // Test mid-sequence asynchronous reset
        areset = 1'b1;
        x = 1'b1;
        #3;
        if (z !== 1'b0) begin
            $display("Async reset during operation failed");
            errors = errors + 1;
        end

        areset = 1'b0;
        check_output(1'b0); // Back in state A, x=1 gives z=1 next cycle

        // Final Result Display
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
